import {chromium,expect} from '@playwright/test';
import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {resolve} from 'node:path';
import {randomUUID,createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {StudioService} from '../../apps/api/dist/studio-service.js';
import {createApplication} from '../../apps/api/dist/app.js';
import {parseConfig} from '../../apps/api/dist/config.js';
const {PrismaClient}=await import('../../apps/api/node_modules/@prisma/client/default.js');process.loadEnvFile('.env');
const admin=new PrismaClient(),dbName='tileset_review_state_'+randomUUID().replaceAll('-','');await admin.$executeRawUnsafe(`CREATE DATABASE "${dbName}"`);const url=new URL(process.env.DATABASE_URL);url.pathname='/'+dbName;execFileSync('pnpm',['--filter','@tileset/api','exec','prisma','migrate','deploy'],{env:{...process.env,DATABASE_URL:url.href},stdio:'pipe'});
const resources=JSON.parse(await readFile('apps/api/dist/resources/studio.json','utf8')),service=new StudioService(parseConfig({...process.env,DATABASE_URL:url.href,NODE_ENV:'production'}),resources,resolve('.local/step07-review/state-skew-assets')),store=service.store,project=await store.createProject('R4 state read consistency'),saved=await store.saveArchives(project.id,[resources.presets.art]);await store.adopt(project.id,0,saved.records[0].built.ir.dependencies);
const originalProject=service.project.bind(service),originalPrepare=store.prepareBuild.bind(store);let armed=false,rowCaptured,releaseRead;const captured=new Promise(r=>rowCaptured=r),readGate=new Promise(r=>releaseRead=r);
store.prepareBuild=async(...args)=>{const p=await originalPrepare(...args);armed=true;await captured;return p;};
service.project=async(...args)=>{const p=await originalProject(...args);if(armed&&args[0]===project.id){armed=false;rowCaptured(p);await readGate;}return p;};
const app=await createApplication(parseConfig({...process.env,DATABASE_URL:url.href,NODE_ENV:'production'}),service);await app.app.listen(4385,'127.0.0.1');const base='http://127.0.0.1:4385',out='.local/step07-review/evidence/state-skew';await mkdir(out,{recursive:true});const browser=await chromium.launch({headless:true}),context=await browser.newContext({viewport:{width:1280,height:960}});await context.tracing.start({screenshots:true,snapshots:true,sources:true});const page=await context.newPage(),log={dbName,assetRoot:'.local/step07-review/state-skew-assets',source:resources.context.commit,network:[],pageErrors:[],scope:'Only a cooperative barrier after genuine project DB row retrieval. Real UI build, real publication/COMMIT, all subsequent metadata queries and actual HTTP body. No JSON/state fabrication.'},bodies=[];page.on('pageerror',e=>log.pageErrors.push(e.message));page.on('response',r=>{if(r.url().includes('/api/'))log.network.push({method:r.request().method(),url:r.url(),status:r.status()});if(r.url().endsWith('/studio'))bodies.push((async()=>{const bytes=await r.body();return {sha256:createHash('sha256').update(bytes).digest('hex'),body:JSON.parse(bytes),bytes:bytes.length}})());});
try{
 await page.goto(base);await page.getByRole('button',{name:project.name,exact:true}).click();await expect.poll(()=>page.getByAltText('当前配方处理水面').evaluate(i=>[i.naturalWidth,i.naturalHeight]),{timeout:15000}).toEqual([96,144]);await expect(page.getByRole('button',{name:'构建当前配套',exact:true})).toBeEnabled();const reply=page.waitForResponse(r=>r.request().method()==='POST'&&r.url().endsWith('/builds'));await page.getByRole('button',{name:'构建当前配套',exact:true}).click();const accepted=await reply;expect(accepted.status()).toBe(202);const job=await accepted.json(),capturedProject=await captured;expect(capturedProject.successfulBuildId).toBe(null);
 let completed;await expect.poll(async()=>{completed=await store.db.studioJob.findUniqueOrThrow({where:{id:job.id}});return completed.state},{timeout:30000,intervals:[100]}).toBe('COMPLETED');const actualProject=await store.db.project.findUniqueOrThrow({where:{id:project.id}});expect(actualProject.successfulBuildId).toBe(completed.buildId);expect(await store.db.finalExport.count({where:{buildId:completed.buildId}})).toBe(1);releaseRead();const row=page.getByRole('list',{name:'构建任务'}).getByRole('listitem').filter({hasText:job.id.slice(0,8)});await expect(row).toContainText('完成');const resolved=await Promise.all(bodies),mixed=resolved.find(x=>x.body.jobs.some(j=>j.id===job.id&&j.state==='COMPLETED'));expect(mixed).toBeTruthy();expect(mixed.body.successfulBuildId).toBe(null);expect(mixed.body.builds.find(b=>b.id===completed.buildId).current).toBe(false);expect(await page.getByLabel('实际构建').inputValue()).toBe('');
 const reads=log.network.filter(x=>x.method==='GET'&&x.url.endsWith('/studio')).length;await page.waitForTimeout(1500);expect(log.network.filter(x=>x.method==='GET'&&x.url.endsWith('/studio')).length).toBe(reads);await row.getByRole('button',{name:'查看这次实际构建',exact:true}).click();await expect(page.locator('canvas[aria-label="交付拼接预览"]')).toHaveAttribute('data-build-id',completed.buildId,{timeout:15000});await expect(page.getByRole('button',{name:'退役旧组并建立第二组',exact:true})).toBeDisabled();await page.screenshot({path:out+'/completed-but-no-current.png',fullPage:true});log.counterexample={capturedProject,completed,actualProject,mixedHTTP:mixed,automaticReadsStopped:reads,retireDisabled:true,manualBuildViewStillWorks:true};const fresh=await(await fetch(base+`/api/projects/${project.id}/studio`)).json();expect(fresh.successfulBuildId).toBe(completed.buildId);expect(fresh.builds.find(b=>b.id===completed.buildId).current).toBe(true);log.freshHTTPControl=fresh;
 await page.reload();await expect(page.locator('canvas[aria-label="交付拼接预览"]')).toHaveAttribute('data-build-id',completed.buildId,{timeout:30000});await expect(page.getByRole('button',{name:'退役旧组并建立第二组',exact:true})).toBeEnabled({timeout:15000});await page.screenshot({path:out+'/reload-current-control.png',fullPage:true});log.result='COUNTEREXAMPLE_CAPTURED';expect(log.pageErrors).toEqual([]);console.log('COUNTEREXAMPLE: actual healthy200 contains COMPLETED with obsolete project pointer; polling stops and retirement remains disabled until reload');
}finally{releaseRead?.();await writeFile(out+'/evidence.json',JSON.stringify(log,null,2)+'\n');await context.tracing.stop({path:'.local/step07-review/private/state-skew-trace.zip'});await browser.close();await app.close();await admin.$disconnect();}
